#!/usr/bin/env python3
"""Print tables, or regenerate/check docs/catalog.md and data/papers.json."""
import argparse
import json
import sys
from catalog import CATEGORIES, ROOT, cell, link_for, markdown_url, read_validated


def render(papers: list[dict]) -> str:
    checked = max(p['verified'] for p in papers)
    lines = [
        '# Paper and Artifact Catalog', '',
        '<!-- Generated by scripts/generate_tables.py; edit papers.yaml instead. -->', '',
        f'{len(papers)} entries. Latest source metadata check: **{checked}**.', '',
        '`status` is an editorial reading role, not peer-review or software maturity.',
        'A paper year uses its verified publication year where known, otherwise its first preprint year.',
        'For evolving software, year identifies the cataloged artifact/snapshot, not a guaranteed first release.',
        '`verified` records a source identity check, not reproduced results or audited code.',
        'A missing code link means no author-associated artifact was verified in this pass.', '',
        '[Engineering guide](practical-guide.md) · [Evaluation guide](evaluation.md) · [Source policy](sources.md)', '',
        '## Contents', '',
    ]
    for category, heading in CATEGORIES.items():
        if any(p['category'] == category for p in papers):
            lines.append(f'- [{heading}](#{category})')
    for category, heading in CATEGORIES.items():
        group = sorted((p for p in papers if p['category'] == category), key=lambda p: (-p['year'], p['id']))
        if not group:
            continue
        lines.extend(['', f'<a name="{category}"></a>', '', f'## {heading}', '',
                      '| Year / venue | Work / artifact | Code | Reading role | Contribution and scope |',
                      '|---|---|---|---|---|'])
        for p in group:
            work = f"<a name=\"{p['id']}\"></a>[{cell(p['title'])}]({markdown_url(link_for(p))})<br>{p['artifact_type']}"
            code = f"[Code]({markdown_url(p['code'])})" if p.get('code') else '—'
            lines.append(f"| {p['year']} / {cell(p['venue'])} | {work} | {code} | {p['status']} | {cell(p['why_it_matters'])}<br>**Scope:** {cell(p['limitation'])} |")
    return '\n'.join(lines) + '\n'


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument('--write', action='store_true', help='Write generated catalog and JSON')
    mode.add_argument('--check', action='store_true', help='Fail if outputs are missing/stale; never writes')
    args = parser.parse_args()
    try:
        papers = read_validated()
        outputs = {
            ROOT / 'docs' / 'catalog.md': render(papers),
            ROOT / 'data' / 'papers.json': json.dumps(papers, indent=2, ensure_ascii=False) + '\n',
        }
        if args.write:
            for path, content in outputs.items():
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding='utf-8')
                print(f'Wrote {path.relative_to(ROOT)}')
        elif args.check:
            stale = [str(path.relative_to(ROOT)) for path, content in outputs.items()
                     if not path.is_file() or path.read_text(encoding='utf-8') != content]
            if stale:
                print('Missing or stale: ' + ', '.join(stale) + '. Run python3 scripts/generate_tables.py --write', file=sys.stderr)
                return 1
            print('Generated catalog and JSON are current.')
        else:
            print(outputs[ROOT / 'docs' / 'catalog.md'], end='')
    except (ValueError, OSError) as exc:
        print(exc, file=sys.stderr)
        return 1
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
